@dataclass(frozen=True)
class CombinedTableRowRec:
    hebrew_range: str
    mam_label: str
    bhs_label: str
    sef_label: str
    note: str = ""


@dataclass(frozen=True)
class CombinedTableGroupRec:
    heading: str
    rows: tuple[CombinedTableRowRec, ...]


def render_combined_table_markdown(books_mpu):
    lines = [
        "## Combined Table: All Differences",
        "",
        "This table treats the Hebrew range as the anchor and shows how each tradition",
        'labels that same span. "↕" means the same Hebrew span has a shifted verse',
        "number; `M+N` means the verse number is shifted by `+N` relative to the MAM",
        'reference shown in the MAM column; "∅" marks a verse number inserted where MAM',
        "has no corresponding Hebrew text.",
        "",
        "<table>",
        "  <thead>",
        "    <tr>",
        '      <th style="text-align:right;">Hebrew range</th>',
        "      <th>MAM verse</th>",
        "      <th>BHS verse</th>",
        "      <th>Sef verse</th>",
        "      <th>Note</th>",
        "    </tr>",
        "  </thead>",
        "  <tbody>",
    ]
    for group in _combined_table_groups(books_mpu):
        lines.extend(_render_group_lines(group))
    lines.extend(
        (
            "  </tbody>",
            "</table>",
            "",
            "**Key:** ⇕ same Hebrew span, renumbered · `M+N` verse number shifted by `+N` from the MAM reference in the MAM column · ∅ verse number inserted where MAM has no corresponding Hebrew text · — no separate label shown in this tradition",
            "",
            "---",
        )
    )
    return "\n".join(lines) + "\n"


def _combined_table_groups(books_mpu):
    return (
        _simple_shift_group(_case("1sam-23-24-boundary"), books_mpu),
        _simple_shift_group(_case("jer-30-31-boundary"), books_mpu),
        _paired_decalogue_group(
            early_case=_case("exod-20-early-decalogue"),
            late_case=_case("exod-20-late-decalogue"),
            heading="Exodus 20",
            books_mpu=books_mpu,
        ),
        _numbers_group(_case("num-25-26-boundary"), books_mpu),
        _paired_decalogue_group(
            early_case=_case("deut-5-early-decalogue"),
            late_case=_case("deut-5-late-decalogue"),
            heading="Deuteronomy 5",
            books_mpu=books_mpu,
        ),
        _joshua_group(_case("josh-21-present-vs-absent"), books_mpu),
    )


def _simple_shift_group(case_rec, books_mpu):
    verses = books_mpu[case_rec.book_id]["verses_plus"]
    anchor_bcvt = case_rec.mam_anchor_bcvt
    shifted_bcvt_seq = _shifted_bcvt_seq(case_rec, verses, tbn.VT_BHS)
    return CombinedTableGroupRec(
        heading=case_data.doc_book_label(case_rec.book_id),
        rows=(
            CombinedTableRowRec(
                hebrew_range=hebrew.range_label_for_minirow(verses[anchor_bcvt]),
                mam_label=_cv_label(anchor_bcvt),
                bhs_label=_mapped_label(tbn.VT_BHS, case_rec.book_id, anchor_bcvt)
                + " ↕",
                sef_label=_mapped_label(tbn.VT_SEF, case_rec.book_id, anchor_bcvt)
                + " ↕",
                note=case_rec.classification,
            ),
            CombinedTableRowRec(
                hebrew_range=hebrew.range_label_for_minirow_span(
                    verses[shifted_bcvt_seq[0]], verses[shifted_bcvt_seq[-1]]
                ),
                mam_label=_cv_range_label(shifted_bcvt_seq[0], shifted_bcvt_seq[-1]),
                bhs_label=_delta_label(tbn.VT_BHS, shifted_bcvt_seq[0]),
                sef_label=_delta_label(tbn.VT_SEF, shifted_bcvt_seq[0]),
            ),
        ),
    )


def _paired_decalogue_group(early_case, late_case, heading, books_mpu):
    verses = books_mpu[early_case.book_id]["verses_plus"]
    early_rows = [
        CombinedTableRowRec(
            hebrew_range=_split_row_label(early_case, split_wtseq, idx),
            mam_label=_cv_label(early_case.mam_anchor_bcvt) + suffix,
            bhs_label=_mapped_part_label(
                tbn.VT_BHS, early_case.book_id, early_case.mam_anchor_bcvt, idx, suffix
            ),
            sef_label=_mapped_part_label(
                tbn.VT_SEF, early_case.book_id, early_case.mam_anchor_bcvt, idx, suffix
            ),
        )
        for idx, (suffix, split_wtseq) in enumerate(
            zip(
                early_case.split_part_suffixes,
                _split_anchor_wtseqs(early_case, verses[early_case.mam_anchor_bcvt].EP),
            )
        )
    ]
    early_shift_start = tbn.mk_bcvtmam(
        early_case.book_id,
        tbn.bcvt_get_chnu(early_case.mam_anchor_bcvt),
        tbn.bcvt_get_vrnu(early_case.mam_anchor_bcvt) + 1,
    )
    early_shift_end = tbn.mk_bcvtmam(
        early_case.book_id,
        tbn.bcvt_get_chnu(early_case.mam_anchor_bcvt),
        early_case.last_shifted_vrnu,
    )
    early_rows.append(
        CombinedTableRowRec(
            hebrew_range=hebrew.range_label_for_minirow_span(
                verses[early_shift_start], verses[early_shift_end]
            ),
            mam_label=_cv_range_label(early_shift_start, early_shift_end),
            bhs_label=_delta_label(tbn.VT_BHS, early_shift_start),
            sef_label=_delta_label(tbn.VT_SEF, early_shift_start),
        )
    )

    late_base_sef_label = _mapped_label(
        tbn.VT_SEF, late_case.book_id, late_case.mam_anchor_bcvt
    )
    late_rows = [
        CombinedTableRowRec(
            hebrew_range=_split_row_label(late_case, split_wtseq, idx),
            mam_label=_cv_label(late_case.mam_anchor_bcvt) + suffix,
            bhs_label=_mapped_part_label(
                tbn.VT_BHS, late_case.book_id, late_case.mam_anchor_bcvt, idx, suffix
            ),
            sef_label=late_base_sef_label + suffix,
        )
        for idx, (suffix, split_wtseq) in enumerate(
            zip(
                late_case.split_part_suffixes,
                _split_anchor_wtseqs(late_case, verses[late_case.mam_anchor_bcvt].EP),
            )
        )
    ]
    late_shift_start = tbn.mk_bcvtmam(
        late_case.book_id,
        tbn.bcvt_get_chnu(late_case.mam_anchor_bcvt),
        tbn.bcvt_get_vrnu(late_case.mam_anchor_bcvt) + 1,
    )
    late_shift_end = tbn.mk_bcvtmam(
        late_case.book_id,
        tbn.bcvt_get_chnu(late_case.mam_anchor_bcvt),
        late_case.last_shifted_vrnu,
    )
    late_rows.append(
        CombinedTableRowRec(
            hebrew_range=hebrew.range_label_for_minirow_span(
                verses[late_shift_start], verses[late_shift_end]
            ),
            mam_label=_cv_range_label(late_shift_start, late_shift_end),
            bhs_label=_delta_label(tbn.VT_BHS, late_shift_start),
            sef_label=_delta_label(tbn.VT_SEF, late_shift_start),
        )
    )
    return CombinedTableGroupRec(heading=heading, rows=tuple(early_rows + late_rows))


