def _joshua_group(case_rec, books_mpu):
    verses = books_mpu[case_rec.book_id]["verses_plus"]
    anchor_bcvt = case_rec.mam_anchor_bcvt
    shifted_bcvt_seq = _shifted_bcvt_seq_same_chapter(case_rec, verses, tbn.VT_BHS)
    rows = [
        CombinedTableRowRec(
            hebrew_range=hebrew.range_label_for_minirow(verses[anchor_bcvt]),
            mam_label=_cv_label(anchor_bcvt),
            bhs_label=_mapped_label(tbn.VT_BHS, case_rec.book_id, anchor_bcvt),
            sef_label=_mapped_label(tbn.VT_SEF, case_rec.book_id, anchor_bcvt),
        )
    ]
    maprec = vtrad_data.BCV_DIC_FROM_MAM_TO_YYY[tbn.VT_BHS][anchor_bcvt]
    rows.extend(
        CombinedTableRowRec(
            hebrew_range="—",
            mam_label="<em>(absent)</em>",
            bhs_label=_cv_label(tbn.mk_bcvt(case_rec.book_id, cvve[0])) + " ∅",
            sef_label=_cv_label(tbn.mk_bcvt(case_rec.book_id, cvve[0])) + " ∅",
            note=case_rec.classification,
        )
        for cvve in maprec[1:]
    )
    rows.append(
        CombinedTableRowRec(
            hebrew_range=hebrew.range_label_for_minirow_span(
                verses[shifted_bcvt_seq[0]], verses[shifted_bcvt_seq[-1]]
            ),
            mam_label=_cv_range_label(shifted_bcvt_seq[0], shifted_bcvt_seq[-1]),
            bhs_label=_delta_label(tbn.VT_BHS, shifted_bcvt_seq[0]),
            sef_label=_delta_label(tbn.VT_SEF, shifted_bcvt_seq[0]),
        )
    )
    return CombinedTableGroupRec(heading="Joshua 21", rows=tuple(rows))


def _render_group_lines(group):
    lines = [
        "    <tr>",
        f'      <th colspan="5" style="text-align:left;">{group.heading}</th>',
        "    </tr>",
    ]
    for row in group.rows:
        lines.extend(
            (
                "    <tr>",
                f'      <td style="text-align:right;">{row.hebrew_range}</td>',
                f"      <td>{row.mam_label}</td>",
            )
        )
        if row.bhs_label == row.sef_label:
            lines.append(
                '      <td colspan="2" style="text-align:center;">'
                + row.bhs_label
                + "</td>"
            )
        else:
            lines.extend(
                (
                    f"      <td>{row.bhs_label}</td>",
                    f"      <td>{row.sef_label}</td>",
                )
            )
        lines.extend((f"      <td>{row.note}</td>", "    </tr>"))
    return lines


def _case(case_id):
    for case_rec in case_data.CASES:
        if case_rec.case_id == case_id:
            return case_rec
    raise KeyError(case_id)


def _mapped_label(vtrad, book_id, mam_bcvt):
    maprec = vtrad_data.BCV_DIC_FROM_MAM_TO_YYY[vtrad][mam_bcvt]
    return _cv_label(tbn.mk_bcvt(book_id, maprec[0][0]))


def _mapped_part_label(vtrad, book_id, mam_bcvt, idx, _suffix):
    maprec = vtrad_data.BCV_DIC_FROM_MAM_TO_YYY[vtrad][mam_bcvt]
    return _cv_label(tbn.mk_bcvt(book_id, maprec[idx][0]))


def _delta_label(vtrad, mam_bcvt):
    mapped_bcvt = tbn.mk_bcvt(
        tbn.bcvt_get_bk39id(mam_bcvt),
        vtrad_data.BCV_DIC_FROM_MAM_TO_YYY[vtrad][mam_bcvt][0][0],
    )
    delta = tbn.bcvt_get_vrnu(mapped_bcvt) - tbn.bcvt_get_vrnu(mam_bcvt)
    assert delta > 0
    return f"M+{delta}"


def _shifted_bcvt_seq(case_rec, verses, vtrad):
    anchor_bcvt = case_rec.mam_anchor_bcvt
    shifted_chnu = tbn.bcvt_get_chnu(anchor_bcvt) + 1
    shifted_rows = []
    for bcvt in verses:
        if tbn.bcvt_get_chnu(bcvt) != shifted_chnu:
            continue
        if vtrad_data.BCV_DIC_FROM_MAM_TO_YYY[vtrad].get(bcvt) is None:
            continue
        shifted_rows.append(bcvt)
    return tuple(shifted_rows)


def _shifted_bcvt_seq_same_chapter(case_rec, verses, vtrad):
    anchor_bcvt = case_rec.mam_anchor_bcvt
    anchor_chnu = tbn.bcvt_get_chnu(anchor_bcvt)
    anchor_vrnu = tbn.bcvt_get_vrnu(anchor_bcvt)
    shifted_rows = []
    for bcvt in verses:
        if tbn.bcvt_get_chnu(bcvt) != anchor_chnu:
            continue
        if tbn.bcvt_get_vrnu(bcvt) <= anchor_vrnu:
            continue
        if vtrad_data.BCV_DIC_FROM_MAM_TO_YYY[vtrad].get(bcvt) is None:
            continue
        shifted_rows.append(bcvt)
    return tuple(shifted_rows)


def _split_anchor_wtseqs(case_rec, ep_wtseq):
    if case_rec.renderer_kind == case_data.RENDERER_KIND_COMPLEX_BOUNDARY:
        assert len(ep_wtseq) == 3
        return ((ep_wtseq[0],), (ep_wtseq[2],))
    if len(ep_wtseq) == 3:
        assert ep_wtseq[1] == " "
        return ((ep_wtseq[0],), (ep_wtseq[2],))
    assert len(ep_wtseq) == 7
    return (
        (ep_wtseq[0],),
        (ep_wtseq[2],),
        (ep_wtseq[4],),
        (ep_wtseq[6],),
    )


def _split_row_label(case_rec, split_wtseq, idx):
    if len(case_rec.split_part_suffixes) == 4 and idx < 3:
        return hebrew.first_two_word_label_for_wtseq(split_wtseq)
    return hebrew.range_label_for_wtseq(split_wtseq)


def _cv_label(bcvt):
    return f"{tbn.bcvt_get_chnu(bcvt)}:{tbn.bcvt_get_vrnu(bcvt)}"


def _cv_range_label(start_bcvt, end_bcvt):
    return (
        f"{tbn.bcvt_get_chnu(start_bcvt)}:{tbn.bcvt_get_vrnu(start_bcvt)}"
        + "–"
        + str(tbn.bcvt_get_vrnu(end_bcvt))
    )
